using EduManageLms.Api.Application; using EduManageLms.Api.Common; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace EduManageLms.Api.Controllers; [ApiController][Route("api/v1/student")][Authorize(Roles="Student")]
public sealed class StudentController(IStudentAnalyticsService svc):ControllerBase{[HttpGet("grades")]public async Task<ActionResult<ApiResponse<IReadOnlyCollection<CourseGradeDto>>>> Grades([FromQuery]string? academicYear,[FromQuery]string? semester,CancellationToken ct)=>Ok(ApiResponse<IReadOnlyCollection<CourseGradeDto>>.Ok(await svc.GetGradesAsync(User.StudentCode()!,academicYear,semester,ct)));[HttpGet("gpa")]public async Task<ActionResult<ApiResponse<StudentGpaDto>>> Gpa(CancellationToken ct)=>Ok(ApiResponse<StudentGpaDto>.Ok(await svc.GetCumulativeGpaAsync(User.StudentCode()!,ct)));[HttpGet("clo-results")]public async Task<ActionResult<ApiResponse<IReadOnlyCollection<CloResultDto>>>> Clo(CancellationToken ct)=>Ok(ApiResponse<IReadOnlyCollection<CloResultDto>>.Ok(await svc.GetCloAsync(User.StudentCode()!,ct)));}
